class _DashboardPageState extends State<DashboardPage> {
  late Future<MapEntry<CurrencyPage, List<NewsModel>>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) => MapEntry(
          results[0] as CurrencyPage,
          results[1] as List<NewsModel>,
        ));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<MapEntry<CurrencyPage, List<NewsModel>>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<MapEntry<CurrencyPage, List<NewsModel>>> snapshot) {
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final CurrencyPage currencyPage = snapshot.data!.key;
          final List<NewsModel> newsList = snapshot.data!.value;

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              // Section title for currencies
              Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: Text(
                  context.loc.currencies,
                  style: context.fonts.semiBold16,
                ),
              ),
              // Currency cards
              for (int i = 0; i < currencyPage.items.length; i++)
                Padding(
                  key: ValueKey(currencyPage.items[i].id),
                  padding: EdgeInsets.only(top: i == 0 ? 0 : 10),
                  child: CurrencyCard(model: currencyPage.items[i]),
                ),
              // Divider between sections
              const SizedBox(height: 24),
              // Section title for news
              Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: Text(
                  context.loc.news,
                  style: context.fonts.semiBold16,
                ),
              ),
              // News cards
              for (int i = 0; i < newsList.length; i++)
                Padding(
                  key: ValueKey(newsList[i].link),
                  padding: EdgeInsets.only(top: i == 0 ? 0 : 16),
                  child: NewsCard(model: newsList[i]),
                ),
            ],
          );
        },
      ),
    );
  }
}
